import{_ as t,o as s,c as o,a5 as a}from"./chunks/framework.BYXPg_yw.js";const b=JSON.parse('{"title":"Bottom LED — C++ Example","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"software/sdk/cpp/led-bottom.md","filePath":"software/sdk/cpp/led-bottom.md","lastUpdated":1792759058000}'),i={name:"software/sdk/cpp/led-bottom.md"};function n(d,e,r,l,h,c){return s(),o("div",null,[...e[0]||(e[0]=[a(`<h1 id="bottom-led-—-c-example" tabindex="-1">Bottom LED — C++ Example <a class="header-anchor" href="#bottom-led-—-c-example" aria-label="Permalink to &quot;Bottom LED — C++ Example&quot;">​</a></h1><p><strong>Source</strong>: <code>rbq_sdk/cpp/example/src/rbq/rbq_led_bottom.cpp</code></p><p>Sets the two <strong>status LEDs under the body</strong> (right and left) and prints the state the robot reports back. It publishes one <code>LedBottom</code> message on <code>rt/rbq/cmd/led_bottom</code>, waits for the 1 Hz <code>LedBottomState</code> on <code>rt/rbq/led_bottom</code>, prints it and exits.</p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><ol><li>Reads <code>interface</code> and optional <code>side mode r g b on_ms off_ms count</code> from the command line.</li><li>Initializes the DDS <code>ChannelFactory</code> on the given interface, creates a <code>Publisher&lt;LedBottom_&gt;</code> on <code>rt/rbq/cmd/led_bottom</code> and a <code>Subscriber&lt;LedBottomState_&gt;</code> on <code>rt/rbq/led_bottom</code>.</li><li>Waits ~500 ms for DDS discovery, fills the <code>LedBottom</code> fields and publishes <strong>once</strong>.</li><li>Waits ~2.5 s for the IF board to apply the setting and report it, prints the last <code>LedBottomState</code> received and exits.</li></ol><p>The on-robot <strong>Network</strong> process receives the command, checks the ranges (the same check as <code>PUT /api/led/bottom</code>) and passes it to Motion, which sends it to the IF board over CAN FD. The IF board holds the setting and reports it back once a second; Network republishes that report on <code>rt/rbq/led_bottom</code>.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>RBQ SDK built and installed — see <a href="/RBQ/nightly/software/sdk/cpp/overview.html">C++ SDK Overview</a>.</li><li>The robot stack running and reachable on the same DDS interface.</li><li><strong>A CAN FD robot.</strong> On other robots Network rejects the command and publishes no state, so the example prints <code>no state on rt/rbq/led_bottom</code>. In the simulator Motion stands in for the IF board and MuJoCo shows the two LEDs under the body, so the example works there too.</li></ul><h2 id="build" tabindex="-1">Build <a class="header-anchor" href="#build" aria-label="Permalink to &quot;Build&quot;">​</a></h2><p>From <code>rbq_sdk/cpp/example/</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/setup.bash</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/build.bash</span></span></code></pre></div><p>Binary: <code>bin/rbq_led_bottom</code></p><h2 id="run" tabindex="-1">Run <a class="header-anchor" href="#run" aria-label="Permalink to &quot;Run {#run}&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./bin-x86_64/rbq_led_bottom</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [interface] [side] [mode] [r] [g] [b] [on_ms] [off_ms] [count]</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Both LEDs steady blue (the defaults) — the interface always comes first:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./bin-x86_64/rbq_led_bottom</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> eth0</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Right LED blinking red, 0.5 s on / 0.5 s off, forever:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./bin-x86_64/rbq_led_bottom</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> eth0</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> right</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> blink</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 255</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 500</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 500</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Both LEDs off:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./bin-x86_64/rbq_led_bottom</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> eth0</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> both</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> off</span></span></code></pre></div><p>All arguments are positional, so <strong>the interface must be the first argument</strong>. Use the interface that reaches the robot — <code>lo</code> when running on the robot PC, your NIC from another host.</p><table tabindex="0"><thead><tr><th>Arg</th><th>Meaning</th><th>Default</th></tr></thead><tbody><tr><td><code>interface</code></td><td>CycloneDDS interface (<code>lo</code> on the robot / NIC from another host)</td><td>—</td></tr><tr><td><code>side</code></td><td><code>right</code> / <code>left</code> / <code>both</code> — the other LED keeps its setting</td><td><code>both</code></td></tr><tr><td><code>mode</code></td><td><code>off</code> / <code>on</code> / <code>blink</code></td><td><code>on</code></td></tr><tr><td><code>r g b</code></td><td>colour, 0–255 each</td><td><code>0 0 255</code></td></tr><tr><td><code>on_ms off_ms</code></td><td>blink on / off time, 10–2550 ms (10 ms steps); ignored unless <code>blink</code></td><td><code>500 500</code></td></tr><tr><td><code>count</code></td><td>blink repeats, <code>0</code> = forever; ignored unless <code>blink</code></td><td><code>0</code></td></tr></tbody></table><p>Out-of-range values are rejected by Network (logged on the robot) and the LEDs stay as they were.</p><h2 id="example-output" tabindex="-1">Example output <a class="header-anchor" href="#example-output" aria-label="Permalink to &quot;Example output&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[rbq_led_bottom] published: side=right mode=blink rgb=255,0,0 on_ms=500 off_ms=500 count=0</span></span>
<span class="line"><span>[rbq_led_bottom] state: age_ms=312 configured=1 if_fw=2026100701</span></span>
<span class="line"><span>  right: mode=blink rgb=255,0,0 on_ms=500 off_ms=500 count=0 actual=255,0,0 lpf_w=0.6</span></span>
<span class="line"><span>  left: mode=on rgb=0,0,255 on_ms=0 off_ms=0 count=0 actual=0,0,255 lpf_w=0.4</span></span></code></pre></div><p>Values depend on the robot. <code>actual</code> is the last output after the IF board&#39;s power limit, and <code>limited</code> appears when that limit reduced the output within the last second. <code>configured=0</code> means the IF board rebooted and holds no setting — Motion resends the last one by itself.</p>`,20)])])}const k=t(i,[["render",n]]);export{b as __pageData,k as default};
